var i=`1129-chicken-and-waffles`;var n=`world-1129`;var a=`US`;var r=`northern-america`;var o=8;var s=125;var l={en:`Chicken and Waffles`,ua:`Курка з вафлями`};var h={en:`Chicken and Waffles is a dish from United States prepared with chicken thigh, buttermilk, all-purpose flour, whole cow milk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Курка з вафлями, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: куряче стегно, сколотини, пшеничне борошно універсальне, цільне коров'яче молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 70 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 70 хвилин.`,t:[`marinating`],m:70,i:[[`chicken-thigh`,750,`g`],[`buttermilk`,350,`ml`],[`table-salt`,8,`g`]]},{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:10,i:[[`all-purpose-flour`,200,`g`],[`smoked-paprika`,6,`g`],[`ground-black-pepper`,4,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 17 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 17 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:17,i:[[`canola-oil`,650,`ml`]]},{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:10,i:[[`all-purpose-flour`,280,`g`],[`whole-cow-milk`,320,`ml`],[`chicken-egg`,2,`pcs`],[`baking-powder`,12,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`unsalted-butter`,40,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:3,i:[[`maple-syrup`,110,`ml`]]}];var u={slug:i,id:n,country:`US`,region:r,servings:8,minutes:125,title:l,text:h,steps:d};export{a as country,u as default,n as id,s as minutes,r as region,o as servings,i as slug,d as steps,h as text,l as title};